(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10;
  const sx = x+w1x, sy = y+w1y;
  const w2x = Math.sin(sx*0.035-t*0.5)*8+Math.cos(sy*0.025+t*0.4)*6;
  const w2y = Math.cos(sy*0.03+t*0.45)*8+Math.sin(sx*0.028-t*0.55)*6;
  const fx = sx+w2x, fy = sy+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 0.7],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.85],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 0.6],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.9],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 0.5],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.75],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+2)*55, 0.11, 2.1, 0.65],
    [400+Math.cos(t*0.55+1)*60, 220+Math.sin(t*0.75+4)*45, 0.05, 2.8, 0.8],
    [200+Math.sin(t*0.7+2)*90, 10+Math.cos(t*0.5+3)*80, 0.13, 1.4, 0.55],
    [300+Math.cos(t*0.38+4)*110, 230+Math.sin(t*0.58+1)*65, 0.075, 2.4, 0.7]
  ];
  let aS=0, iS=0, cS=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((fx-sX)**2+(fy-sY)**2);
    const wv = Math.sin(d*f-t*sp);
    const wv2 = Math.sin(d*f*1.618-t*sp*0.618+0.5);
    aS += wv*w + wv2*(1-w);
    iS += Math.sin(d*f*0.7+t*sp*0.6+1.5)*w + Math.sin(d*f*1.13-t*sp*0.4+2.1)*(1-w);
    cS += Math.cos(d*f*0.5+t*sp*0.3)*w + Math.cos(d*f*0.85+t*sp*0.5+1.0)*(1-w);
  }
  const act=aS/10, inh=iS/10, cross=cS/10;
  const turb1 = Math.sin(fx*0.04+fy*0.025+t*0.8)+Math.sin(fx*0.03-fy*0.04+t*1.1);
  const turb2 = Math.sin((fx+fy)*0.12+t*2.5)*0.2+Math.sin((fx-fy)*0.1-t*2)*0.2;
  const turb3 = Math.sin(fx*0.08+Math.cos(fy*0.06+t*0.3)*3+t*0.7)*0.15;
  const bg = (turb1+turb2+turb3)/2;
  const dist = Math.sqrt((fx-cx)**2+(fy-cy)**2), ang = Math.atan2(fy-cy, fx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const spiral2 = Math.sin(dist*0.03+ang*5+t*0.8)*Math.cos(dist*0.07-ang*2-t*1.1)*0.2;
  const reaction = Math.tanh((act - inh*0.7 + bg*0.3 + spiral + spiral2 + cross*0.15)*2.2);
  const cell = Math.tanh((Math.sin(fx*0.15)*Math.sin(fy*0.15)+Math.sin((fx+fy)*0.1+t)*0.5)*1.5)*0.3;
  const micro = Math.sin(fx*0.3+fy*0.2+t*3)*Math.sin(fx*0.2-fy*0.3-t*2.5)*0.1;
  const blend = reaction*0.6 + cell*0.25 + micro*0.15;
  const v = blend*0.5+0.5;
  const pal = [
    [5,10,42],[10,35,72],[12,65,95],[18,110,120],[30,155,140],
    [120,185,100],[210,195,65],[230,145,55],[215,95,60],
    [180,55,75],[120,30,60],[60,18,50],[20,12,45],[5,10,42]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.75+Math.sin(reaction*Math.PI)*0.25;
  const edge = Math.abs(reaction)>0.65?1.0+Math.abs(reaction)*0.2:1.0;
  const glow = Math.max(0, reaction)*0.15;
  const r0 = pal[i][0]+(pal[i+1][0]-pal[i][0])*f;
  const g0 = pal[i][1]+(pal[i+1][1]-pal[i][1])*f;
  const b0 = pal[i][2]+(pal[i+1][2]-pal[i][2])*f;
  return [
    Math.min(255, (r0*lum*edge+glow*180))|0,
    Math.min(255, (g0*lum*edge+glow*140))|0,
    Math.min(255, (b0*lum*edge+glow*100))|0
  ];
}
